gOO(){return"\u0420\u0435\u0433\u0438\u043e\u043d 1 \u043f\u043e\u0434\u0445\u043e\u0434\u0438\u0442 \u0434\u043b\u044f \u043d\u0430\u0441\u0435\u043b\u0451\u043d\u043d\u044b\u0445 \u043f\u0443\u043d\u043a\u0442\u043e\u0432 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d\u0430\u0445 1\u20133, \u0440\u0435\u0433\u0438\u043e\u043d 2 \u2014 \u0434\u043b\u044f 2\u20133, \u0440\u0435\u0433\u0438\u043e\u043d 3 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f 3. \u0420\u0435\u0433\u0438\u043e\u043d \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u0438 \u0441\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441 \u043c\u0435\u0441\u0442\u043e\u043c \u0443\u0445\u043e\u0434\u0430, \u0430 \u043d\u0435 \u0441 \u0433\u043e\u0440\u043e\u0434\u043e\u043c \u043f\u0440\u043e\u0436\u0438\u0432\u0430\u043d\u0438\u044f \u0441\u0438\u0434\u0435\u043b\u043a\u0438."},
