ga70(){return"Gesher B1 \u0441\u043e\u0435\u0434\u0438\u043d\u044f\u0435\u0442 \u0441\u0435\u043c\u044c\u0438 \u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u0435 \u0441 \u0441\u0438\u0434\u0435\u043b\u043a\u0430\u043c\u0438 \u0434\u043b\u044f \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b \u0438\u043b\u0438 \u0437\u0430\u043c\u0435\u043d\u044b. \u0421\u0435\u043c\u044c\u0438 \u043f\u043b\u0430\u0442\u044f\u0442 \u0437\u0430 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u044b\u0439 \u043f\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u0430\u043c \u0438 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u043a\u0435. \u0421\u0438\u0434\u0435\u043b\u043a\u0438 \u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u043e. \u041c\u044b \u043d\u0435 \u0431\u0435\u0440\u0451\u043c \u043f\u043b\u0430\u0442\u0443 \u0437\u0430 \u0441\u0430\u043c \u0443\u0445\u043e\u0434 \u0438 \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u043c \u043f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0443\u044e \u043a\u0432\u0430\u043b\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044e"},
ga7d(){return"\u041a\u0430\u043a\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0441\u043e\u0431\u0438\u0440\u0430\u044e\u0442\u0441\u044f"},
ga76(){return"\u0410\u043a\u043a\u0430\u0443\u043d\u0442: \u043d\u043e\u043c\u0435\u0440 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 (\u0434\u043b\u044f \u0432\u0445\u043e\u0434\u0430 \u043f\u043e SMS-\u043a\u043e\u0434\u0443), \u044f\u0437\u044b\u043a \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430, \u0440\u043e\u043b\u044c \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435"},
ga78(){return"\u0421\u0435\u043c\u044c\u044f: \u0433\u043e\u0440\u043e\u0434, \u044f\u0437\u044b\u043a\u0438, \u0434\u0430\u0442\u044b \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043d\u0430 \u043d\u0430\u0439\u043c (\u0431\u0435\u0437 \u0444\u0430\u0439\u043b\u0430), \u0434\u0430\u0442\u044b \u0437\u0430\u043c\u0435\u043d\u044b, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u043e \u043f\u043e\u0434\u043e\u043f\u0435\u0447\u043d\u044b\u0445 \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0432 \u0434\u043e\u043c\u0435, \u043d\u0443\u0436\u043d\u044b\u0435 \u0434\u043b\u044f \u043f\u043e\u0434\u0431\u043e\u0440\u0430"},
ga77(){return"\u0421\u0438\u0434\u0435\u043b\u043a\u0430: \u0438\u043c\u044f, \u0444\u043e\u0442\u043e, \u0433\u0440\u0430\u0436\u0434\u0430\u043d\u0441\u0442\u0432\u043e, \u0433\u043e\u0440\u043e\u0434\u0430 \u0440\u0430\u0431\u043e\u0442\u044b, \u044f\u0437\u044b\u043a\u0438, \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u044c \u0438 \u043e\u043f\u044b\u0442, \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c, \u0441\u0440\u043e\u043a \u043f\u0440\u0435\u0431\u044b\u0432\u0430\u043d\u0438\u044f \u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u0435 \u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0430 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f \u043f\u0440\u043e\u0448\u043b\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b"},
ga7e(){return"\u0412\u0438\u0437\u0430: PDF-\u0444\u0430\u0439\u043b \u0438 \u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 \u0441\u0440\u043e\u043a \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f. \u0424\u0430\u0439\u043b \u0437\u0430\u043a\u0440\u044b\u0442, \u0435\u0433\u043e \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u0443\u043f\u043e\u043b\u043d\u043e\u043c\u043e\u0447\u0435\u043d\u043d\u044b\u0439 \u0441\u043e\u0442\u0440\u0443\u0434\u043d\u0438\u043a, \u0438 \u043e\u043d \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044f \u0441\u0435\u043c\u044c\u044f\u043c"},
